package main

import (
	"log"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/pocketbase/pocketbase/core"
)

// guestStaleAfter is how long an unconverted guest account (and its
// associated game_states record, via CascadeDelete) is kept before cleanup.
const guestStaleAfter = 30 * 24 * time.Hour

// guestUsernamePrefix matches usernames generated by web/lib/guestAuth.ts.
const guestUsernamePrefix = "guest_"

// registerGuestAccountCleanup schedules a daily job that deletes guest user
// records (and their cascaded game_states) that were created
// more than guestStaleAfter ago and never upgraded to a full account.
func registerGuestAccountCleanup(app core.App) {
	app.Cron().MustAdd("guest_account_cleanup", "0 3 * * *", func() {
		cleanupStaleGuestAccounts(app)
	})
}

func cleanupStaleGuestAccounts(app core.App) {
	users, err := app.FindCollectionByNameOrId("users")
	if err != nil {
		log.Printf("guest cleanup: users collection not found: %v", err)
		return
	}

	cutoff := time.Now().Add(-guestStaleAfter)
	records, err := app.FindRecordsByFilter(
		users.Id,
		"username ~ {:prefix} && created < {:cutoff}",
		"-created",
		0,
		0,
		map[string]any{
			"prefix": guestUsernamePrefix + "%",
			"cutoff": cutoff,
		},
	)
	if err != nil {
		log.Printf("guest cleanup: query failed: %v", err)
		return
	}

	for _, rec := range records {
		if !strings.HasPrefix(rec.GetString("username"), guestUsernamePrefix) {
			continue
		}
		if err := app.Delete(rec); err != nil {
			log.Printf("guest cleanup: failed to delete %s: %v", rec.Id, err)
			continue
		}
		log.Printf("guest cleanup: deleted stale guest account %s", rec.Id)
	}
}

// guestSignupRateLimiter throttles guest account creation per client IP to
// prevent abuse (mass account creation, orphaned game_states records).
type guestSignupRateLimiter struct {
	mu       sync.Mutex
	attempts map[string][]time.Time
	limit    int
	window   time.Duration
}

func newGuestSignupRateLimiter(limit int, window time.Duration) *guestSignupRateLimiter {
	return &guestSignupRateLimiter{
		attempts: make(map[string][]time.Time),
		limit:    limit,
		window:   window,
	}
}

func (l *guestSignupRateLimiter) allow(ip string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := time.Now()
	cutoff := now.Add(-l.window)

	kept := l.attempts[ip][:0]
	for _, t := range l.attempts[ip] {
		if t.After(cutoff) {
			kept = append(kept, t)
		}
	}

	if len(kept) >= l.limit {
		l.attempts[ip] = kept
		return false
	}

	l.attempts[ip] = append(kept, now)
	return true
}

// registerGuestSignupRateLimit blocks guest user creation requests once a
// single IP exceeds 5 signups within 10 minutes.
func registerGuestSignupRateLimit(app core.App) {
	limiter := newGuestSignupRateLimiter(5, 10*time.Minute)

	app.OnRecordCreateRequest("users").BindFunc(func(e *core.RecordRequestEvent) error {
		username := e.Record.GetString("username")
		if !strings.HasPrefix(username, guestUsernamePrefix) {
			return e.Next()
		}

		ip := e.RequestEvent.RealIP()
		if !limiter.allow(ip) {
			return e.JSON(http.StatusTooManyRequests, map[string]string{
				"message": "Too many guest accounts created from this address. Please try again later.",
			})
		}

		return e.Next()
	})
}
